function sitemap_fx_forum($forum_id)
{
    global $sitemap_config;
    $url = make_url(&#039;/&#039;);

    $sitemap_file = &quot;&lt;?xml version=\&quot;1.0\&quot; encoding=\&quot;UTF-8\&quot; ?&gt;\n&quot;;
