        FROM &#039; . BB_TOPICS . &#039;
            WHERE forum_id = &#039; . $forum_id;
    $result = DB()-&gt;sql_query($sql);

    while ($row = DB()-&gt;sql_fetchrow($result))
    {
        $lastmod = date($row[&#039;topic_last_post_time&#039;]);
        $pages = $row[&#039;topic_replies&#039;] / $sitemap_config[&#039;posts_per_page&#039;];
