            }
            $sitemap_file .= &quot;&lt;lastmod&gt;&quot; . $lastmod = Date(&#039;Y-m-d&#039;) . &quot;&lt;/lastmod&gt;\n&quot;;
            switch ($row[&#039;topic_type&#039;])
            {
                case POST_NORMAL:
                    $sitemap_file .= &quot;&lt;changefreq&gt;&quot; . $sitemap_config[&#039;sitemap_freq_0&#039;] . &quot;&lt;/changefreq&gt;\n&quot;;
